"""Owned finite CPU/idle subprocess; only the child's affinity/name are changed."""
import copy,json,os,pathlib,signal,subprocess,sys,time

WORKER='''import ctypes,json,os,signal,sys,time
affinity=sorted(os.sched_getaffinity(0));os.sched_setaffinity(0,affinity[:min(2,len(affinity))])
ctypes.CDLL(None).prctl(15,b'cpu ) worker',0,0,0)
signal.signal(signal.SIGTERM,lambda *args:sys.exit(0))
print(json.dumps({'pid':os.getpid(),'allowed_cpus':sorted(os.sched_getaffinity(0))}),flush=True)
if sys.argv[1]=='busy':
 end=time.monotonic()+6;x=1
 while time.monotonic()<end:x=(x*1103515245+12345)%2147483647
else:time.sleep(6)
'''

def raw_sample(pid):
    raw=pathlib.Path('/proc',str(pid),'stat').read_text();tail=raw.rsplit(')',1)[1].split()
    return {'pid':pid,'starttime':int(tail[19]),'utime':int(tail[11]),'stime':int(tail[12]),'clock_ticks':os.sysconf('SC_CLK_TCK'),'allowed_cpus':sorted(os.sched_getaffinity(pid)),'timestamp_ns':time.monotonic_ns()}

def probe(measure,mode,interval_ms):
    if mode not in('busy','idle'):raise ValueError('invalid owned worker mode')
    parent=(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'),sorted(os.sched_getaffinity(0)))
    proc=subprocess.Popen([sys.executable,'-B','-c',WORKER,mode],stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True);samples=[];pauses=[]
    try:
        ready=json.loads(proc.stdout.readline())
        if ready['pid']!=proc.pid:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: owned PID identity mismatch')
        if len(ready['allowed_cpus'])<2:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: two allowed CPUs required for this denominator comparison')
        def read():
            row=raw_sample(proc.pid);samples.append(copy.deepcopy(row));return row
        def pause(seconds):pauses.append(seconds);time.sleep(seconds)
        result=measure(read,pause,interval_ms)
        if len(samples)!=2:raise AssertionError('must actually take two native samples')
        if mode=='busy'and samples[1]['utime']+samples[1]['stime']<=samples[0]['utime']+samples[0]['stime']:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: owned busy worker received no measurable ticks')
        ledger={'mode':mode,'owned_pid':proc.pid,'ready':ready,'samples':samples,'pause_requests':pauses,'result':result,'raw_comm':pathlib.Path('/proc',str(proc.pid),'comm').read_text().strip()}
    finally:
        if proc.poll()is None:
            proc.terminate()
            try:proc.wait(timeout=2)
            except subprocess.TimeoutExpired:proc.kill();proc.wait(timeout=2)
        stdout,stderr=proc.communicate(timeout=2)
        assert parent==(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'),sorted(os.sched_getaffinity(0)))
        print('OWNED_CPU_CLEANUP:'+json.dumps({'pid':proc.pid,'exit_code':proc.returncode,'reaped':proc.poll()is not None,'parent_identity_environment_affinity_unchanged':True}),flush=True)
    ledger.update(exit_code=proc.returncode,reaped=True,worker_stderr=stderr);return ledger

