    if not callable(read_sample)or not callable(pause)or type(interval_ms)is not int or not 20<=interval_ms<=250:raise ValueError('invalid measurement request')
    before=read_sample();pause(interval_ms/1000);after=read_sample()
    for field in ('pid','starttime','clock_ticks','allowed_cpus'):
